213	     */
214	    public Pet getPet(String name) {
215	        return getPet(name, false);
216	    }
217	
218	    /**
219	     * Return the Pet with the given name, or null if none found for this Owner.
220	     *
221	     * @param name to test
222	     * @return true if pet name is already in use
223	     */
224	    public Pet getPet(String name, boolean ignoreNew) {
225	        name = name.toLowerCase();
226	        for (Pet pet : getPetsInternal()) {
227	            if (!ignoreNew || !pet.isNew()) {
228	                String compName = pet.getName();
229	                compName = compName.toLowerCase();
230	                if (compName.equals(name)) {
231	                    return pet;
232	                }
233	            }
234	        }
235	        return null;
236	    }
237	
238	    public Pet getPet(Integer petId) {
239	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
240	    }
