242	    @Override
243	    public String toString() {
244	        return new ToStringCreator(this)
245	
246	            .append("id", this.getId())
247	            .append("new", this.isNew())
248	            .append("lastName", this.getLastName())
249	            .append("firstName", this.getFirstName())
250	            .append("address", this.address)
251	            .append("city", this.city)
252	            .append("telephone", this.telephone)
253	            .append("email", this.email)
254	            .toString();
255	    }
256	}
